using SharpCompress.Archives;

public void ListZipContents(string zipPath)
{
    using var archive = ArchiveFactory.Open(zipPath);
    foreach (var entry in archive.Entries.Where(e => !e.IsDirectory))
    {
        Console.WriteLine($"{entry.Key} - {entry.Size} bytes");
    }
}

using SharpCompress.Writers;
using SharpCompress.Writers.Zip;

public void CreateZip(string outputPath, IEnumerable<string> files)
{
    using var stream = File.Create(outputPath);
    using var writer = WriterFactory.Open(stream, ArchiveType.Zip, CompressionType.Deflate);

    foreach (var file in files)
    {
        writer.Write(Path.GetFileName(file), File.OpenRead(file));
    }
}
